		description = "",
		hidden = true
	)
	default Point bankOffset()
	{
		return null;
	}
}

package com.setuppicker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the picker: as a popup while it has been opened with the hotkey, otherwise beside the bank
 * whenever the bank is open.
 */
@Singleton
public class SetupPickerOverlay extends Overlay
{
	private static final int PALETTE_WIDTH = 240;

	private final Client client;
	private final SetupPickerConfig config;
	private final PickerModel model;
	private final ItemManager itemManager;

	// Layout of the last rendered frame, read by the input listeners. Null while the picker isn't showing.
	private volatile PickerLayout layout;
	private volatile String status = "";
	private volatile Point mouse;
	// Where the bank and the canvas were in the last rendered frame that had the list beside the bank
	private volatile Point bankCorner;
	private volatile Rectangle canvas;
	// While the list beside the bank is being dragged: where its corner is from the bank's. Else null.
	private volatile Point dragOffset;

	@Inject
	SetupPickerOverlay(Client client, SetupPickerConfig config, PickerModel model, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.model = model;
		this.itemManager = itemManager;
		// Positions itself, in canvas coordinates
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public PickerLayout getLayout()
	{
		return layout;
	}

	/**
	 * Message to show in place of the list when there are no setups.
	 */
	public void setStatus(String status)
	{
		this.status = status;
	}

	public void clearLayout()
	{
		layout = null;
		mouse = null;
		dragOffset = null;
	}

	/**
	 * Show the list beside the bank with its top left corner here on the canvas, while it is being dragged.
	 */
	public void dragTo(Point corner)
	{
		final Point bank = bankCorner;
		if (bank != null)
		{
			dragOffset = new Point(corner.x - bank.x, corner.y - bank.y);
		}
	}

	/**
	 * Where the list has been dragged to, from the bank's top left corner and kept on the canvas, for saving.
	 * Null if it hasn't been.
	 */
	public Point getDragOffset()
	{
		final Point offset = dragOffset;
		final Point bank = bankCorner;
		final Rectangle area = canvas;
		if (offset == null || bank == null || area == null)
		{
			return null;
		}
		final Point corner = PickerLayout.clamp(new Point(bank.x + offset.x, bank.y + offset.y), config.width(), area);
		return new Point(corner.x - bank.x, corner.y - bank.y);
	}

	/**
	 * Go back to showing the list where it is saved as being.
	 */
	public void endDrag()
	{
		dragOffset = null;
	}

	/**
	 * @param mouse where the mouse is over the picker, which is kept from the game (see PickerInput), or null
	 *              when it's elsewhere
	 */
	public void setMouse(Point mouse)
	{
		this.mouse = mouse;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final PickerModel.View view = model.view();
		final int rowHeight = config.showIcons() ? PickerLayout.ROW_HEIGHT_ICONS : PickerLayout.ROW_HEIGHT_TEXT;
		final PickerLayout newLayout;
		// which side of the picker its box of notes goes on, given the choice
		boolean notesOnLeft = false;
		if (view.isPaletteOpen())
		{
			newLayout = PickerLayout.computePalette(new Rectangle(client.getCanvasWidth(), client.getCanvasHeight()),
				PALETTE_WIDTH, view.getRows().size(), rowHeight, config.popupRows());
		}
		else
		{
			final Widget bank = config.showBesideBank() ? client.getWidget(InterfaceID.Bankmain.UNIVERSE) : null;
			if (bank == null || bank.isHidden())
			{
				layout = null;
				return null;
			}
			final Rectangle area = new Rectangle(client.getCanvasWidth(), client.getCanvasHeight());
			final Point dragged = dragOffset;
			final Point offset = dragged != null ? dragged : config.bankOffset();
			if (offset != null)
			{
				newLayout = PickerLayout.computeMoved(bank.getBounds(), area, offset, config.width(), config.collapsed(),
					view.getRows().size(), rowHeight, config.bankRows());
			}
			else
			{
				newLayout = PickerLayout.compute(bank.getBounds(), area.width,
					config.side() == SetupPickerConfig.Side.LEFT, config.width(), config.collapsed(), config.verticalWhenCollapsed(),
					view.getRows().size(), rowHeight, config.bankRows());
			}
			bankCorner = bank.getBounds().getLocation();
			canvas = area;
			// away from the bank, rather than over it
			notesOnLeft = newLayout.getBounds().x < bank.getBounds().x;
		}
		// clamps the scroll position to what now fits, so take the view afterwards
		model.setVisibleRows(newLayout.getVisibleRows());
		layout = newLayout;

		// over the picker the game doesn't know where the mouse is; anywhere else it does
		final Point hidden = mouse;
		final net.runelite.api.Point seen = client.getMouseCanvasPosition();
		// unless the picker has since moved out from under it
		final Point hover = hidden != null && newLayout.getBounds().contains(hidden) ? hidden : (seen == null ? null : new Point(seen.getX(), seen.getY()));
		final PickerTheme theme = new PickerTheme(config.backgroundColor(), config.headerColor(), config.borderColor(),
			config.accentColor(), config.textColor());
		final String title = config.source() == SetupPickerConfig.Source.BANK_TAGS ? "Bank tags" : "Setups";
		final PickerPainter painter = new PickerPainter(theme, title);
		final PickerModel.View clamped = model.view();
		painter.paint(graphics, newLayout, clamped,
			hover,
			config.showIcons() ? itemManager::getImage : null,
			FontManager.getRunescapeSmallFont(), status);
		painter.paintNotes(graphics, newLayout, clamped, hover, FontManager.getRunescapeSmallFont(),
			new Rectangle(client.getCanvasWidth(), client.getCanvasHeight()), notesOnLeft);
		return null;
	}
}

package com.setuppicker;

import com.google.inject.Binder;
import com.google.inject.Provides;
import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Inventory Setups Picker",
	description = "Hotkey search for your Inventory Setups and Bank Tag Layouts: open any setup or bank tag by typing its name",
	tags = {"inventory", "setups", "loadout", "preset", "gear", "bank", "tags", "tag", "layout", "layouts", "hotkey", "search", "quick", "switch", "picker"}
)
// for its BankTagsService
@PluginDependency(BankTagsPlugin.class)
public class SetupPickerPlugin extends Plugin
{
	private static final String INVENTORY_SETUPS_PLUGIN_NAME = "Inventory Setups";
	private static final String BANK_TAGS_PLUGIN_NAME = "Bank Tags";
	// The latest version with something new to tell of, and what is said about it, once, at the next login.
	// A release with nothing to announce leaves both as they are.
	static final String NEWS_VERSION = "1.3.0";
	static final String NEWS = "Inventory Setups Picker " + NEWS_VERSION + ": drag the list beside the bank by its title"
		+ " bar to put it anywhere (right-click the title bar to put it back), and limit its height with the new Max rows setting.";

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ChatboxKeyGuard chatboxKeyGuard;

	@Inject
	private SetupPickerConfig config;

	@Inject
	private SetupRepository repository;

	@Inject
	private PickerModel model;

	@Inject
	private SetupPickerOverlay overlay;

	@Inject
	private PickerInput input;

	@Inject
	private SpellbookOverlay spellbookOverlay;

	private final AtomicBoolean refreshQueued = new AtomicBoolean();
	private final RecentTagTracker recentTagTracker = new RecentTagTracker();
	// The names of the bank tags listed, by their standardized form. Client thread only.
	private Map<String, String> bankTagNames = Collections.emptyMap();

	@Override
	public void configure(Binder binder)
	{
		binder.bind(PickerModel.class).asEagerSingleton();
	}

	@Provides
	SetupPickerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SetupPickerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(spellbookOverlay);
		mouseManager.registerMouseListener(input);
		mouseManager.registerMouseWheelListener(input);
		keyManager.registerKeyListener(input);

		queueRefresh();
		// Inventory Setups only announces the active setup when it changes, so ask once for the current one
		clientThread.invokeLater(() ->
		{
			model.setActiveSetup(repository.queryActiveSetup());
			recentTagTracker.reset();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(spellbookOverlay);
		mouseManager.unregisterMouseListener(input);
		mouseManager.unregisterMouseWheelListener(input);
		keyManager.unregisterKeyListener(input);
		clientThread.invoke(chatboxKeyGuard::restore);
		overlay.clearLayout();
		model.resetSearch();
	}

	@Subscribe
	public void onPluginMessage(PluginMessage message)
	{
		if (!SetupRepository.NAMESPACE.equals(message.getNamespace()))
		{
			return;
		}
		if (SetupRepository.MSG_SETUPS_CHANGED.equals(message.getName()))
		{
			queueRefresh();
		}
		else if (SetupRepository.MSG_ACTIVE_SETUP_CHANGED.equals(message.getName()))
		{
			final Object active = message.getData().get(SetupRepository.DATA_ACTIVE_SETUP);
			final String name = active instanceof String ? (String) active : "";
			model.setActiveSetup(name);
			if (!name.isEmpty() && config.source().hasSetups())
			{
				// This message also comes for every edit to the open setup, which leaves the list as it is
				markUsed(name);
			}
		}
	}

	/**
	 * @param key the key of the setup or bank tag that has just been opened
	 */
	private void markUsed(String key)
	{
		if (config.recentCount() <= 0)
		{
			return;
		}
		// Saving it is a config change of this plugin's, which reloads the list in its new order
		final List<String> recent = repository.loadRecent();
		final List<String> updated = SetupRepository.markUsed(recent, key);
		if (updated != recent)
		{
			repository.saveRecent(updated);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Favoriting, recoloring or changing a setup's icon rewrites its saved json without a setups-changed message
		// and neither does anything done to a section
		final boolean setupEdited = SetupRepository.CONFIG_GROUP.equals(event.getGroup())
			&& (event.getKey().startsWith(SetupRepository.CONFIG_KEY_SETUP_PREFIX)
			|| SetupRepository.CONFIG_KEY_SECTIONS.equals(event.getKey()));
		// creating, deleting, renaming or reordering tag tabs, or changing a tab's icon
		final boolean bankTagEdited = SetupRepository.BANK_TAGS_CONFIG_GROUP.equals(event.getGroup())
			&& (SetupRepository.BANK_TAGS_TABS_KEY.equals(event.getKey())
			|| event.getKey().startsWith(SetupRepository.BANK_TAGS_ICON_PREFIX));
		if (SetupPickerConfig.GROUP.equals(event.getGroup()) && SetupPickerConfig.KEY_SIDE.equals(event.getKey()))
		{
			// choosing a side puts a list that has been dragged elsewhere back beside the bank
			setBankOffset(null);
		}
		if (setupEdited || bankTagEdited || SetupPickerConfig.GROUP.equals(event.getGroup()))
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(recentTagTracker::reset);
		queueRefresh();
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		final String name = event.getPlugin().getName();
		if (INVENTORY_SETUPS_PLUGIN_NAME.equals(name) || BANK_TAGS_PLUGIN_NAME.equals(name))
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			queueRefresh();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		// the popup is independent of the bank, so only a search in the list beside it ends here
		if (event.getGroupId() == InterfaceID.BANKMAIN && !model.view().isPaletteOpen())
		{
			model.resetSearch();
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		chatboxKeyGuard.sync(model.view().isSearchFocused());

		// Bank Tags has no message for its open tag changing, so keep an eye on it
		// Under the name it's listed by, as Bank Tags doesn't mind how a tag's name is capitalized. One that isn't
		// listed counts as none: Inventory Setups opens a tag of its own to filter the bank.
		final String bankTag = bankTagNames.getOrDefault(Text.standardize(repository.queryActiveBankTag()), "");
		model.setActiveBankTag(bankTag);
		if (recentTagTracker.observe(bankTag))
		{
			markUsed(SetupEntry.bankTagKey(bankTag));
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Nothing is drawn outside the game, so don't leave the keyboard captured by an invisible popup
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			recentTagTracker.reset();
			model.resetSearch();
		}
		else if (!NEWS_VERSION.equals(config.lastSeenVersion()))
		{
			// This state comes again after every loading screen, so it's marked as seen before anything else
			configManager.setConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_SEEN_VERSION, NEWS_VERSION);
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(new ChatMessageBuilder().append(ChatColorType.HIGHLIGHT).append(NEWS).build())
				.build());
		}
	}

	/**
	 * Open the setup, or close it if it's the one already open. A bank tag is opened either way, which for the
	 * one already open changes nothing, the same as clicking its tab.
	 */
	void toggleSetup(SetupEntry setup)
	{
		if (!setup.isBankTag() && model.view().isActive(setup))
		{
			clientThread.invoke(() -> repository.close(setup.getName()));
		}
		else
		{
			openSetup(setup);
		}
	}

	void openSetup(SetupEntry setup)
	{
		if (setup.isBankTag())
		{
			// the next client tick sees it open, and counts it as recently used
			clientThread.invoke(() -> repository.openBankTag(setup.getName()));
		}
		else
		{
			clientThread.invoke(() -> repository.open(setup.getName()));
		}
	}

	void setCollapsed(boolean collapsed)
	{
		configManager.setConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_COLLAPSED, collapsed);
	}

	/**
	 * @param offset where the list beside the bank has been dragged to, from the bank's top left corner, or null
	 *               to put it back at the bank's side
	 */
	void setBankOffset(Point offset)
	{
		if (offset == null)
		{
			configManager.unsetConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_BANK_OFFSET);
		}
		else
		{
			configManager.setConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_BANK_OFFSET, offset);
		}
	}

	// Several triggers tend to fire together (e.g. every setup's config key on a profile switch), so
	// collapse them into one reload on the client thread.
	private void queueRefresh()
	{
		if (refreshQueued.compareAndSet(false, true))
		{
			clientThread.invokeLater(() ->
			{
				refreshQueued.set(false);
				final List<String> used = repository.loadRecent();
				final List<String> recent = used.subList(0, Math.max(0, Math.min(config.recentCount(), used.size())));
				final SetupPickerConfig.Source source = config.source();
				final boolean setupsOn = isPluginEnabled(INVENTORY_SETUPS_PLUGIN_NAME);
				final boolean bankTagsOn = isPluginEnabled(BANK_TAGS_PLUGIN_NAME);
				final List<SetupEntry> setups = new ArrayList<>();
				// whatever is listed, the open setup's spellbook can be shown on the bank
				final Map<String, Integer> spellbooks = new HashMap<>();
				for (SetupEntry setup : repository.loadSetups(config.alphabetical(), config.favoritesFirst()))
				{
					if (source.hasSetups())
					{
						setups.add(setup);
					}
					if (setup.getSpellbook() != SetupEntry.NO_SPELLBOOK)
					{
						spellbooks.put(setup.getName(), setup.getSpellbook());
					}
				}
				spellbookOverlay.setSpellbooks(spellbooks);
				final Map<String, String> tagNames = new HashMap<>();
				// its tabs stay saved while Bank Tags is off, but can't be opened
				if (source.hasBankTags() && bankTagsOn)
				{
					for (SetupEntry tag : repository.loadBankTags())
					{
						setups.add(tag);
						tagNames.put(Text.standardize(tag.getName()), tag.getName());
					}
					SetupRepository.sort(setups, config.alphabetical(), config.favoritesFirst());
				}
				bankTagNames = tagNames;
				final List<SetupSection> sections = config.groupBySection() && source.hasSetups()
					? repository.loadSections() : Collections.emptyList();
				model.setSectionPages(config.sectionPages());
				model.setFuzzySearch(config.fuzzySearch());
				model.setShowNotes(config.showNotes());
				model.setStartOnActiveSetup(config.startOnOpenSetup());
				model.setRows(SetupRepository.group(setups, sections, config.alphabetical(), config.favoritesFirst(), recent), setups.size());
				overlay.setStatus(status(source, setupsOn, bankTagsOn));
			});
		}
	}

	/**
	 * What to say in place of an empty list.
	 */
	static String status(SetupPickerConfig.Source source, boolean setupsOn, boolean bankTagsOn)
	{
		switch (source)
		{
			case BANK_TAGS:
				return bankTagsOn ? "No bank tags yet" : "Bank Tags is off";
			case BOTH:
				return setupsOn || bankTagsOn ? "Nothing to list yet" : "Both plugins are off";
			default:
				return setupsOn ? "No setups yet" : "Inventory Setups is off";
		}
	}

	private boolean isPluginEnabled(String name)
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (name.equals(plugin.getName()))
			{
				return pluginManager.isPluginEnabled(plugin);
			}
		}
		return false;
	}
}

package com.setuppicker;

import com.google.common.hash.Hashing;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Talks to the Inventory Setups plugin. Hub plugins live in separate classloaders, so everything goes
 * through its PluginMessage API (see InventorySetupsPluginMessageHandler in that plugin) or its saved config.
 * Also reads and opens the tag tabs of the client's own Bank Tags plugin.
 */
@Singleton
public class SetupRepository
{
	private static final Logger log = LoggerFactory.getLogger(SetupRepository.class);

	static final String NAMESPACE = "inventory-setups";
	static final String MSG_SETUPS_CHANGED = "setups-changed";
	static final String MSG_ACTIVE_SETUP_CHANGED = "active-setup-changed";
	private static final String MSG_GET_SETUPS = "get-setups";
	private static final String MSG_GET_ACTIVE_SETUP_CONTENTS = "get-active-setup-contents";
	private static final String MSG_VIEW = "view";
	private static final String MSG_CLEAR = "clear";
	private static final String DATA_SETUPS = "setups";
	private static final String DATA_SETUP = "setup";
	static final String DATA_ACTIVE_SETUP = "activeSetup";

	// Inventory Setups stores each setup as json under setupsV3_<murmur3_128 of the name>
	static final String CONFIG_GROUP = "inventorysetups";
	private static final int MAX_RECENT = 10;

	static final String CONFIG_KEY_SETUP_PREFIX = "setupsV3_";
	// and all the sections together, as a json array
	static final String CONFIG_KEY_SECTIONS = "sections";

	// Bank Tags keeps its tabs as a csv of their names, and each tab's icon under icon_<standardized name>
	static final String BANK_TAGS_CONFIG_GROUP = "banktags";
	static final String BANK_TAGS_TABS_KEY = "tagtabs";
	static final String BANK_TAGS_ICON_PREFIX = "icon_";

	private final EventBus eventBus;
	private final ConfigManager configManager;
	private final Gson gson;
	private final BankTagsService bankTagsService;

	@Inject
	SetupRepository(EventBus eventBus, ConfigManager configManager, Gson gson, BankTagsService bankTagsService)
	{
		this.eventBus = eventBus;
		this.configManager = configManager;
		this.gson = gson;
		this.bankTagsService = bankTagsService;
	}

	/**
	 * All bank tag tabs, in the order of the Bank Tags plugin's tabs. Unlike Inventory Setups, Bank Tags is part
	 * of the client, so its service can be used directly.
	 */
	public List<SetupEntry> loadBankTags()
	{
		final String savedTabs = configManager.getConfiguration(BANK_TAGS_CONFIG_GROUP, BANK_TAGS_TABS_KEY);
		final List<String> names = Text.fromCSV(savedTabs == null ? "" : savedTabs);
		final List<SetupEntry> tags = new ArrayList<>(names.size());
		for (String name : names)
		{
			// Same fallback as Bank Tags' own tabs: the spade
			int iconItemId = ItemID.SPADE;
			try
			{
				final String icon = configManager.getConfiguration(BANK_TAGS_CONFIG_GROUP, BANK_TAGS_ICON_PREFIX + Text.standardize(name));
				if (icon != null)
				{
					iconItemId = Integer.parseInt(icon);
				}
			}
			catch (NumberFormatException e)
			{
				log.debug("Couldn't read the icon of bank tag {}", name, e);
			}
			tags.add(SetupEntry.bankTag(name, iconItemId));
		}
		return tags;
	}

	/**
	 * Name of the bank tag currently open, or "" when there is none. Call on the client thread.
	 */
	public String queryActiveBankTag()
	{
		final String active = bankTagsService.getActiveTag();
		return active == null ? "" : active;
	}

	/**
	 * Open a bank tag, along with its layout if it has one, as if its tab was clicked.
	 */
	public void openBankTag(String name)
	{
		bankTagsService.openBankTag(name, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
	}

	/**
	 * All setups. Empty if Inventory Setups isn't running.
	 *
	 * @param alphabetical sort by name, rather than keeping the order of Inventory Setups' own list
	 */
	public List<SetupEntry> loadSetups(boolean alphabetical, boolean favoritesFirst)
	{
		// post() is synchronous: Inventory Setups fills the collection before it returns
		final List<String> names = new ArrayList<>();
		final Map<String, Object> data = new HashMap<>();
		data.put(DATA_SETUPS, names);
		eventBus.post(new PluginMessage(NAMESPACE, MSG_GET_SETUPS, data));

		final List<SetupEntry> setups = new ArrayList<>(names.size());
		for (String name : names)
		{
			final String hash = Hashing.murmur3_128().hashUnencodedChars(name).toString();
			setups.add(parseSetup(gson, name, configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_SETUP_PREFIX + hash)));
		}
		return Collections.unmodifiableList(sort(setups, alphabetical, favoritesFirst));
	}

	static List<SetupEntry> sort(List<SetupEntry> setups, boolean alphabetical, boolean favoritesFirst)
	{
		if (alphabetical)
		{
			setups.sort((a, b) -> String.CASE_INSENSITIVE_ORDER.compare(a.getName(), b.getName()));
		}
		if (favoritesFirst)
		{
			// stable, so favorites and the rest each keep the order they have by now
			setups.sort((a, b) -> Boolean.compare(b.isFavorite(), a.isFavorite()));
		}
		return setups;
	}

	/**
	 * Puts a setup at the front of the recently used, which are kept latest first and capped in number.
	 *
	 * @param name the setup's key: its name, or for a bank tag {@link SetupEntry#bankTagKey}
	 * @return the new list, or the same one if the setup was already at the front
	 */
	static List<String> markUsed(List<String> recent, String name)
	{
		if (!recent.isEmpty() && recent.get(0).equals(name))
		{
			return recent;
		}
		final List<String> updated = new ArrayList<>(recent.size() + 1);
		updated.add(name);
		for (String other : recent)
		{
			if (!other.equals(name) && updated.size() < MAX_RECENT)
			{
				updated.add(other);
			}
		}
		return updated;
	}

	/**
	 * The keys of the recently used setups and bank tags saved by {@link #saveRecent}, latest first.
	 */
	public List<String> loadRecent()
	{
		try
		{
			final String[] names = gson.fromJson(configManager.getConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_RECENT), String[].class);
			return names == null ? Collections.emptyList() : Arrays.asList(names);
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read the recently used setups", e);
			return Collections.emptyList();
		}
	}

	public void saveRecent(List<String> recent)
	{
		configManager.setConfiguration(SetupPickerConfig.GROUP, SetupPickerConfig.KEY_RECENT, gson.toJson(recent));
	}

	/**
	 * Builds the list entry for a setup from its saved json. The name comes from the API, so a setup whose
	 * json is missing or unreadable still gets listed, just without its icon, color, favorite flag and notes.
	 */
	static SetupEntry parseSetup(Gson gson, String name, String json)
	{
		boolean favorite = false;
		Color displayColor = null;
		int iconItemId = -1;
		String notes = "";
		int spellbook = SetupEntry.NO_SPELLBOOK;
		try
		{
			final JsonObject setup = json == null ? null : gson.fromJson(json, JsonObject.class);
			if (setup != null)
			{
				favorite = setup.has("fv") && setup.get("fv").getAsBoolean();
				if (setup.has("dc"))
				{
					displayColor = gson.fromJson(setup.get("dc"), Color.class);
				}
				if (setup.has("notes") && setup.get("notes").isJsonPrimitive())
				{
					notes = setup.get("notes").getAsString().trim();
				}
				// Left out when it's the standard one, which is 0. 4 is for "none".
				spellbook = setup.has("sb") ? setup.get("sb").getAsInt() : 0;
				if (spellbook < 0 || spellbook > 3)
				{
					spellbook = SetupEntry.NO_SPELLBOOK;
				}
				if (setup.has("iId"))
				{
					iconItemId = setup.get("iId").getAsInt();
				}
				if (iconItemId <= 0)
				{
					// Same fallback as Inventory Setups' icon view: the weapon
					iconItemId = itemIdAt(setup.getAsJsonArray("eq"), EquipmentInventorySlot.WEAPON.getSlotIdx());
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read saved data for setup {}", name, e);
		}
		if (iconItemId <= 0)
		{
			iconItemId = ItemID._100GUIDE_GUIDECAKE;
		}
		return new SetupEntry(name, favorite, displayColor, iconItemId, notes, spellbook);
	}

	/**
	 * The sections setups are grouped into, in the order of Inventory Setups' side panel. There is no API for
	 * these, so they are read from where Inventory Setups saves them.
	 */
	public List<SetupSection> loadSections()
	{
		return parseSections(gson, configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_SECTIONS));
	}

	/**
	 * Reads the saved sections, skipping any that can't be made sense of.
	 */
	static List<SetupSection> parseSections(Gson gson, String json)
	{
		final List<SetupSection> sections = new ArrayList<>();
		try
		{
			final JsonArray saved = json == null ? null : gson.fromJson(json, JsonArray.class);
			if (saved == null)
			{
				return sections;
			}
			for (JsonElement element : saved)
			{
				if (!element.isJsonObject() || !element.getAsJsonObject().has("name"))
				{
					continue;
				}
				final JsonObject section = element.getAsJsonObject();
				final List<String> setupNames = new ArrayList<>();
				if (section.has("setups") && section.get("setups").isJsonArray())
				{
					for (JsonElement setup : section.getAsJsonArray("setups"))
					{
						setupNames.add(setup.getAsString());
					}
				}
				final Color displayColor = section.has("displayColor") ? gson.fromJson(section.get("displayColor"), Color.class) : null;
				sections.add(new SetupSection(section.get("name").getAsString(), displayColor, Collections.unmodifiableList(setupNames)));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Couldn't read the saved sections", e);
		}
		return sections;
	}

	/**
	 * Lays the setups out under a heading per section, followed by the ones in no section. A setup is listed
	 * under every section it is in. Without any sections in use, it's just the setups.
	 *
	 * @param setups       every setup, in the order to list them
	 * @param alphabetical sort each section by name, rather than keeping the order it has in Inventory Setups
	 */
	static List<PickerRow> group(List<SetupEntry> setups, List<SetupSection> sections, boolean alphabetical, boolean favoritesFirst)
	{
		return group(setups, sections, alphabetical, favoritesFirst, Collections.emptyList());
	}

	/**
	 * @param setups may have bank tags among them. Those aren't in any section, so when the list is in sections
	 *               they go under a heading of their own at the end.
	 * @param recent keys of the recently used setups to list at the top, latest first. Empty for none. When
	 *               the list is in sections they get a heading of their own and are listed in their sections
	 *               as well; otherwise they are simply moved to the top.
	 */
	static List<PickerRow> group(List<SetupEntry> setups, List<SetupSection> sections, boolean alphabetical, boolean favoritesFirst,
		List<String> recent)
	{
		final Map<String, SetupEntry> byKey = new HashMap<>();
		for (SetupEntry setup : setups)
		{
			byKey.put(setup.getKey(), setup);
		}

		final List<PickerRow> rows = new ArrayList<>();
		final Set<String> assigned = new HashSet<>();
		for (SetupSection section : sections)
		{
			final List<SetupEntry> members = new ArrayList<>();
			for (String name : section.getSetupNames())
			{
				// a setup's key is its name, so this never finds a bank tag that happens to be called the same
				final SetupEntry setup = byKey.get(name);
				if (setup != null)
				{
					members.add(setup);
				}
			}
			if (members.isEmpty())
			{
				continue;
			}
			rows.add(PickerRow.header(section));
			for (SetupEntry setup : sort(members, alphabetical, favoritesFirst))
			{
				rows.add(PickerRow.of(setup));
				assigned.add(setup.getKey());
			}
		}

		final boolean sectioned = !rows.isEmpty();

		final List<PickerRow> recentRows = new ArrayList<>();
		for (String key : recent)
		{
			// one that has since been deleted or renamed is just left out
			final SetupEntry setup = byKey.get(key);
			if (setup != null)
			{
				recentRows.add(PickerRow.recent(setup));
				if (!sectioned)
				{
					assigned.add(key);
				}
			}
		}
		if (!recentRows.isEmpty())
		{
			if (sectioned)
			{
				recentRows.add(0, PickerRow.RECENT);
			}
			rows.addAll(0, recentRows);
		}

		if (!sectioned)
		{
			for (SetupEntry setup : setups)
			{
				if (!assigned.contains(setup.getKey()))
				{
					rows.add(PickerRow.of(setup));
				}
			}
			return rows;
		}
		addUnder(rows, PickerRow.UNASSIGNED, setups, assigned, false);
		addUnder(rows, PickerRow.BANK_TAGS, setups, assigned, true);
		return rows;
	}

	/**
	 * Lists the setups that aren't in a section, or the bank tags, under a heading that is left out if there are none.
	 */
	private static void addUnder(List<PickerRow> rows, PickerRow heading, List<SetupEntry> setups, Set<String> assigned, boolean bankTags)
	{
		boolean headed = false;
		for (SetupEntry setup : setups)
		{
			if (setup.isBankTag() != bankTags || assigned.contains(setup.getKey()))
			{
				continue;
			}
			if (!headed)
			{
				rows.add(heading);
				headed = true;
			}
			rows.add(PickerRow.of(setup));
		}
	}

	private static int itemIdAt(JsonArray items, int index)
	{
		if (items == null || index >= items.size())
		{
			return -1;
		}
		// empty slots are saved as null
		final JsonElement item = items.get(index);
		return item.isJsonObject() && item.getAsJsonObject().has("id") ? item.getAsJsonObject().get("id").getAsInt() : -1;
	}

	/**
	 * Name of the setup currently open in Inventory Setups, or "" when there is none or it can't be told
	 * (the API only reports setups that filter the bank). Call on the client thread, where the reply is
	 * synchronous.
	 */
	public String queryActiveSetup()
	{
		final Map<String, Object> data = new HashMap<>();
		data.put("equipmentItemIds", new ArrayList<Integer>());
		data.put("inventoryItemIds", new ArrayList<Integer>());
		data.put("additionalItemIds", new ArrayList<Integer>());
		eventBus.post(new PluginMessage(NAMESPACE, MSG_GET_ACTIVE_SETUP_CONTENTS, data));
		final Object active = data.get(DATA_ACTIVE_SETUP);
		return active instanceof String ? (String) active : "";
	}

	/**
	 * Open a setup in Inventory Setups, as if picked from its side panel.
	 */
	public void open(String name)
	{
		eventBus.post(new PluginMessage(NAMESPACE, MSG_VIEW, Map.of(DATA_SETUP, name)));
	}

	/**
	 * Close a setup, if it is still the one that's open.
	 */
	public void close(String name)
	{
		eventBus.post(new PluginMessage(NAMESPACE, MSG_CLEAR, Map.of(DATA_SETUP, name)));
	}
}

package com.setuppicker;

import java.awt.Color;
import java.util.List;

/**
 * A section from Inventory Setups: a named group of setups. A setup can be in several, or none.
 */
public final class SetupSection
{
	private final String name;
	private final Color displayColor;
	private final List<String> setupNames;

	public SetupSection(String name, Color displayColor, List<String> setupNames)
	{
		this.name = name;
		this.displayColor = displayColor;
		this.setupNames = setupNames;
	}

	public String getName()
	{
		return name;
	}

	/**
	 * The color the user gave the section in Inventory Setups, or null for none.
	 */
	public Color getDisplayColor()
	{
		return displayColor;
	}

	/**
	 * Names of the section's setups, in the order Inventory Setups lists them.
	 */
	public List<String> getSetupNames()
	{
		return setupNames;
	}
}

package com.setuppicker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Collections;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Says under the bank which spellbook the open setup is for, in red when it isn't the one the player is on.
 */
@Singleton
public class SpellbookOverlay extends Overlay
{
	// What Inventory Setups saves for a setup's spellbook, which for these is also the game's own numbering
	private static final String[] SPELLBOOKS = {"Standard", "Ancient", "Lunar", "Arceuus"};

	private static final Color RIGHT = new Color(190, 180, 160);
	private static final Color WRONG = new Color(255, 70, 70);

	// Under the bank's bottom right corner
	private static final int INSET = 6;
	private static final int GAP = 3;
	private static final int PADDING_X = 5;
	private static final int PADDING_Y = 3;

	private final Client client;
	private final SetupPickerConfig config;
	private final PickerModel model;

	// Each setup's spellbook by its name, for the ones that have one
	private volatile Map<String, Integer> spellbooks = Collections.emptyMap();

	@Inject
	SpellbookOverlay(Client client, SetupPickerConfig config, PickerModel model)
	{
		this.client = client;
		this.config = config;
		this.model = model;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public void setSpellbooks(Map<String, Integer> spellbooks)
	{
		this.spellbooks = spellbooks;
	}

	/**
	 * What to say about a setup's spellbook, or null for nothing: when it has none, or one this doesn't know.
	 *
	 * @param wanted  the setup's spellbook, as Inventory Setups numbers them
	 * @param current the spellbook the player is on
	 */
	static String label(int wanted, int current)
	{
		if (wanted < 0 || wanted >= SPELLBOOKS.length)
		{
			return null;
		}
		return wanted == current ? SPELLBOOKS[wanted] + " spellbook" : "Needs " + SPELLBOOKS[wanted] + " spellbook";
	}

	/**
	 * The color, a little more see-through.
	 */
	private static Color muted(Color color)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() * 3 / 4);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showSpellbook())
		{
			return null;
		}
		final Integer wanted = spellbooks.get(model.view().getActiveSetup());
		final Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (wanted == null || bank == null || bank.isHidden())
		{
			return null;
		}
		final int current = client.getVarbitValue(VarbitID.SPELLBOOK);
		final String label = label(wanted, current);
		if (label == null)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics fm = graphics.getFontMetrics();
		final Rectangle bounds = bank.getBounds();
		final int width = fm.stringWidth(label) + 2 * PADDING_X;
		final int height = fm.getAscent() + fm.getDescent() + 2 * PADDING_Y;
		final Rectangle box = new Rectangle(bounds.x + bounds.width - INSET - width, bounds.y + bounds.height + GAP, width, height);
		if (box.y + box.height > client.getCanvasHeight())
		{
			// no room under the bank: just inside its bottom edge instead
			box.y = bounds.y + bounds.height - INSET - height;
		}

		// the picker's own background, toned down, so that the text can be read over whatever is behind it
		graphics.setColor(muted(config.backgroundColor()));
		graphics.fill(box);
		graphics.setColor(muted(config.borderColor()));
		graphics.drawRect(box.x, box.y, box.width - 1, box.height - 1);

		final int x = box.x + PADDING_X;
		final int baseline = box.y + PADDING_Y + fm.getAscent();
		graphics.setColor(Color.BLACK);
		graphics.drawString(label, x + 1, baseline + 1);
		graphics.setColor(wanted == current ? RIGHT : WRONG);
		graphics.drawString(label, x, baseline);
		return null;
	}
}

package com.setuppicker;

import java.awt.Canvas;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class PickerInputTest
{
	private final Canvas canvas = new Canvas();
	private int platformModifier = InputEvent.CTRL_DOWN_MASK;
	private boolean requireModifier = true;
	private PickerModel model;
	private PickerInput input;

	@Before
	public void setUp()
	{
		final Client client = (Client) Proxy.newProxyInstance(getClass().getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getCanvas":
						return canvas;
					case "getGameState":
						return GameState.LOGGED_IN;
					default:
						throw new UnsupportedOperationException(method.getName());
				}
			});
		final SetupPickerConfig config = new SetupPickerConfig()
		{
			@Override
			public boolean requireModifier()
			{
				return requireModifier;
			}
		};
		model = new PickerModel();
		final List<SetupEntry> setups = new ArrayList<>();
		for (String name : new String[]{"Vorkath", "Zulrah", "Wintertodt", "Slayer", "Barrows"})
		{
			setups.add(new SetupEntry(name, false, null, 1));
		}
		model.setSetups(setups);
		model.setVisibleRows(5);
		input = new PickerInput(client, null, config, new SetupPickerOverlay(client, config, model, null), model,
			new PlatformModifier(null)
			{
				@Override
				public int get()
				{
					return platformModifier;
				}
			});
	}

	/**
	 * Delivers a key event the way KeyManager would.
	 *
	 * @param physicalKey the key actually pressed, which real events carry as the extended key code
	 * @param keyCode     the event's key code, which differs from physicalKey once a remapping plugin has had it
	 * @return whether the picker consumed the event
	 */
	private boolean send(int id, int modifiers, int physicalKey, int keyCode, char keyChar)
	{
		final KeyEvent e = new KeyEvent(canvas, id, 0, modifiers, keyCode, keyChar)
		{
			@Override
			public int getExtendedKeyCode()
			{
				return physicalKey;
			}
		};
		switch (id)
		{
			case KeyEvent.KEY_PRESSED:
				input.keyPressed(e);
				break;
			case KeyEvent.KEY_TYPED:
				input.keyTyped(e);
				break;
			default:
				input.keyReleased(e);
				break;
		}
		return e.isConsumed();
	}

	private boolean send(int id, int modifiers, int keyCode, char keyChar)
	{
		return send(id, modifiers, keyCode, keyCode, keyChar);
	}

	// a full press, type, release of a character key, as AWT delivers it
	private void tap(int keyCode, char c)
	{
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, keyCode, c));
		assertTrue(send(KeyEvent.KEY_TYPED, 0, KeyEvent.VK_UNDEFINED, c));
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, keyCode, c));
	}

	private void openWithHotkey()
	{
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertTrue(send(KeyEvent.KEY_TYPED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_UNDEFINED, (char) 0x0b));
		assertTrue(send(KeyEvent.KEY_RELEASED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertTrue(model.view().isPaletteOpen());
	}

	@Test
	public void keysPassThroughWhileClosed()
	{
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_W, 'w'));
		assertFalse(send(KeyEvent.KEY_TYPED, 0, KeyEvent.VK_UNDEFINED, 'w'));
		assertFalse(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_W, 'w'));
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_ENTER, '\n'));
	}

	@Test
	public void typingFiltersWithoutDoubling()
	{
		openWithHotkey();
		tap(KeyEvent.VK_S, 's');
		tap(KeyEvent.VK_W, 'w');
		assertEquals("sw", model.view().getQuery());
		assertEquals(0, model.view().getSelected());
		tap(KeyEvent.VK_BACK_SPACE, '\b');
		assertEquals("s", model.view().getQuery());
		assertEquals(2, model.view().getRows().size());
	}

	@Test
	public void keysRewrittenByKeyRemappingAreStillTyped()
	{
		openWithHotkey();
		// Key Remapping has turned S into Down and W into Up, blanked their characters, and consumed the
		// typed events, so those never arrive
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_S, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_S, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertEquals("s", model.view().getQuery());
		assertEquals(0, model.view().getSelected());

		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.SHIFT_DOWN_MASK, KeyEvent.VK_W, KeyEvent.VK_UP, KeyEvent.CHAR_UNDEFINED));
		assertEquals("sW", model.view().getQuery());
		assertEquals(0, model.view().getSelected());
	}

	@Test
	public void numberKeysRewrittenToFunctionKeysAreStillTyped()
	{
		openWithHotkey();
		// Platform Keys sends 1 as F1, and Key Remapping can do the same
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_1, KeyEvent.VK_F1, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_NUMPAD2, KeyEvent.VK_F2, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_SPACE, KeyEvent.VK_CONTROL, KeyEvent.CHAR_UNDEFINED));
		assertEquals("12 ", model.view().getQuery());
		// a real function key types nothing
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_F5, KeyEvent.CHAR_UNDEFINED));
		assertEquals("12 ", model.view().getQuery());
	}

	@Test
	public void arrowsNavigateAndEscapeCloses()
	{
		openWithHotkey();
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_UP, KeyEvent.CHAR_UNDEFINED));
		assertEquals("Zulrah", model.getSelectedSetup().getName());

		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_ESCAPE, (char) 0x1b));
		assertFalse(model.view().isPaletteOpen());
		// the release of the key that closed it doesn't leak to the game either
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_ESCAPE, (char) 0x1b));
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_DOWN, KeyEvent.CHAR_UNDEFINED));
	}

	@Test
	public void hotkeyTogglesAndItsCharacterIsNotTyped()
	{
		openWithHotkey();
		assertEquals("", model.view().getQuery());
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertFalse(model.view().isPaletteOpen());
	}

	@Test
	public void keyHeldBeforeOpeningIsStillReleasedToTheGame()
	{
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_W, 'w'));
		openWithHotkey();
		assertFalse(send(KeyEvent.KEY_RELEASED, 0, KeyEvent.VK_W, 'w'));
	}

	@Test
	public void hotkeyUsesThePlatformModifier()
	{
		platformModifier = InputEvent.META_DOWN_MASK;
		// Ctrl+K is not the shortcut on a Mac, and neither is K alone or Cmd+Shift+K
		assertFalse(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertFalse(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_K, 'k'));
		assertFalse(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK, KeyEvent.VK_K, 'K'));
		assertFalse(model.view().isPaletteOpen());

		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK, KeyEvent.VK_K, 'k'));
		assertTrue(model.view().isPaletteOpen());
		// Cmd+K leaves a typed 'k' on some systems; it isn't put in the search box
		assertTrue(send(KeyEvent.KEY_TYPED, InputEvent.META_DOWN_MASK, KeyEvent.VK_UNDEFINED, 'k'));
		assertEquals("", model.view().getQuery());

		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK, KeyEvent.VK_K, 'k'));
		assertFalse(model.view().isPaletteOpen());
	}

	@Test
	public void hotkeyWithoutModifierStaysTypeable()
	{
		requireModifier = false;
		assertFalse(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_K, (char) 0x0b));
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, KeyEvent.VK_K, 'k'));
		assertTrue(send(KeyEvent.KEY_TYPED, 0, KeyEvent.VK_UNDEFINED, 'k'));
		assertTrue(model.view().isPaletteOpen());
		assertEquals("", model.view().getQuery());

		// now it's a letter like any other
		tap(KeyEvent.VK_K, 'k');
		assertTrue(model.view().isPaletteOpen());
		assertEquals("k", model.view().getQuery());
	}

	@Test
	public void platformKeysProfileOverridesTheComputer()
	{
		assertEquals(InputEvent.META_DOWN_MASK, PlatformModifier.resolve(null, true));
		assertEquals(InputEvent.CTRL_DOWN_MASK, PlatformModifier.resolve(null, false));
		assertEquals(InputEvent.META_DOWN_MASK, PlatformModifier.resolve("AUTO", true));
		assertEquals(InputEvent.CTRL_DOWN_MASK, PlatformModifier.resolve("WINDOWS", true));
		assertEquals(InputEvent.META_DOWN_MASK, PlatformModifier.resolve("MAC", false));
	}

	@Test
	public void selectAllHighlightsTheSearchTextForReplacing()
	{
		openWithHotkey();
		tap(KeyEvent.VK_S, 's');
		tap(KeyEvent.VK_L, 'l');

		// Cmd+A, then typing replaces what was there
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK, KeyEvent.VK_A, 'a'));
		assertTrue(model.view().isQuerySelected());
		assertEquals("sl", model.view().getQuery());
		tap(KeyEvent.VK_Z, 'z');
		assertEquals("z", model.view().getQuery());
		assertFalse(model.view().isQuerySelected());

		// Ctrl+A, then Backspace clears it in one go
		tap(KeyEvent.VK_U, 'u');
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_A, (char) 1));
		assertTrue(model.view().isQuerySelected());
		tap(KeyEvent.VK_BACK_SPACE, '\b');
		assertEquals("", model.view().getQuery());
		assertFalse(model.view().isQuerySelected());

		// nothing to highlight in an empty box, and a plain "a" is still just a letter
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.META_DOWN_MASK, KeyEvent.VK_A, 'a'));
		assertFalse(model.view().isQuerySelected());
		tap(KeyEvent.VK_A, 'a');
		assertEquals("a", model.view().getQuery());
	}

	private void press(int keyCode)
	{
		assertTrue(send(KeyEvent.KEY_PRESSED, 0, keyCode, KeyEvent.CHAR_UNDEFINED));
		assertTrue(send(KeyEvent.KEY_RELEASED, 0, keyCode, KeyEvent.CHAR_UNDEFINED));
	}

	@Test
	public void cursorMovesThroughTheSearchText()
	{
		openWithHotkey();
		tap(KeyEvent.VK_S, 's');
		tap(KeyEvent.VK_A, 'a');
		tap(KeyEvent.VK_Y, 'y');
		assertEquals(3, model.view().getCaret());

		// back one and insert the missing letter
		press(KeyEvent.VK_LEFT);
		press(KeyEvent.VK_LEFT);
		tap(KeyEvent.VK_L, 'l');
		assertEquals("slay", model.view().getQuery());
		assertEquals(2, model.view().getCaret());
		assertEquals("Slayer", model.getSelectedSetup().getName());

		// Backspace takes the letter before the cursor, Delete the one after
		tap(KeyEvent.VK_BACK_SPACE, '\b');
		assertEquals("say", model.view().getQuery());
		tap(KeyEvent.VK_DELETE, (char) KeyEvent.VK_DELETE);
		assertEquals("sy", model.view().getQuery());
		assertEquals(1, model.view().getCaret());

		// the ends, which it doesn't run past
		press(KeyEvent.VK_HOME);
		press(KeyEvent.VK_LEFT);
		assertEquals(0, model.view().getCaret());
		tap(KeyEvent.VK_BACK_SPACE, '\b');
		assertEquals("sy", model.view().getQuery());
		press(KeyEvent.VK_END);
		press(KeyEvent.VK_RIGHT);
		assertEquals(2, model.view().getCaret());

		// after select all, an arrow drops the highlight and goes to that end
		assertTrue(send(KeyEvent.KEY_PRESSED, InputEvent.CTRL_DOWN_MASK, KeyEvent.VK_A, (char) 1));
		press(KeyEvent.VK_LEFT);
		assertFalse(model.view().isQuerySelected());
		assertEquals(0, model.view().getCaret());
		assertEquals("sy", model.view().getQuery());
	}
}

package com.setuppicker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class PickerModelTest
{
	private PickerModel model;

	@Before
	public void setUp()
	{
		model = new PickerModel();
		final List<SetupEntry> setups = new ArrayList<>();
		for (String name : new String[]{"Vorkath", "Zulrah", "Vardorvis", "ToA 300", "Barrows", "Slayer melee", "Slayer range"})
		{
			setups.add(new SetupEntry(name, false, null, 1));
		}
		model.setSetups(setups);
		model.setVisibleRows(3);
	}

	private void type(String text)
	{
		for (char c : text.toCharArray())
		{
			model.typeChar(c);
		}
	}

	@Test
	public void typingFiltersIgnoringCase()
	{
		model.openPalette();
		type("SLAY");
		assertEquals(2, model.view().getRows().size());
		assertEquals("Slayer melee", model.getSelectedSetup().getName());
		assertEquals(7, model.view().getTotal());

		model.backspace();
		model.backspace();
		model.backspace();
		model.backspace();
		assertEquals(7, model.view().getRows().size());
	}

	@Test
	public void noMatchesSelectsNothing()
	{
		model.openPalette();
		type("zzz");
		assertTrue(model.view().getRows().isEmpty());
		assertNull(model.getSelectedSetup());
		model.moveSelection(1);
		assertNull(model.getSelectedSetup());
	}

	@Test
	public void selectionStaysInRangeAndOnScreen()
	{
		model.openPalette();
		model.moveSelection(-1);
		assertEquals(0, model.view().getSelected());

		model.moveSelection(4);
		assertEquals("Barrows", model.getSelectedSetup().getName());
		// 3 rows fit, so the selection is the last visible one
		assertEquals(2, model.view().getScroll());

		model.pageSelection(5);
		assertEquals("Slayer range", model.getSelectedSetup().getName());
		assertEquals(4, model.view().getScroll());

		model.pageSelection(-1);
		assertEquals(3, model.view().getSelected());
		assertEquals(3, model.view().getScroll());
	}

	@Test
	public void scrollIsClampedToTheList()
	{
		model.scrollBy(100);
		assertEquals(4, model.view().getScroll());
		model.scrollBy(-100);
		assertEquals(0, model.view().getScroll());

		// everything fits: nothing to scroll
		model.setVisibleRows(20);
		model.scrollBy(3);
		assertEquals(0, model.view().getScroll());
	}

	@Test
	public void openingThePaletteStartsFresh()
	{
		model.setSearchFocused(true);
		type("vor");
		model.openPalette();
		assertTrue(model.view().isPaletteOpen());
		assertTrue(model.view().isSearchFocused());
		assertEquals("", model.view().getQuery());
		assertEquals(7, model.view().getRows().size());

		model.resetSearch();
		assertFalse(model.view().isPaletteOpen());
		assertFalse(model.view().isSearchFocused());
	}

	@Test
	public void filterSurvivesSetupsReloading()
	{
		model.openPalette();
		type("vor");
		final List<SetupEntry> reloaded = new ArrayList<>();
		reloaded.add(new SetupEntry("Vorkath", true, null, 1));
		reloaded.add(new SetupEntry("Vorkath (dhcb)", false, null, 1));
		reloaded.add(new SetupEntry("Zulrah", false, null, 1));
		model.setSetups(reloaded);
		assertEquals(2, model.view().getRows().size());
		assertEquals("vor", model.view().getQuery());
	}

	@Test
	public void pickingFromTheUnfilteredListKeepsItsScrollPosition()
	{
		model.scrollBy(4);
		// what clicking a row does, followed by the reload Inventory Setups' config change triggers
		model.resetSearch();
		assertEquals(4, model.view().getScroll());
		model.setRows(model.view().getRows(), 7);
		assertEquals(4, model.view().getScroll());

		// the popup starts at the top, and leaves the list beside the bank where it was
		model.openPalette();
		assertEquals(0, model.view().getScroll());
		type("s");
		model.resetSearch();
		assertEquals(4, model.view().getScroll());
	}

	@Test
	public void clearingAFilterGoesBackToTheTop()
	{
		model.setSearchFocused(true);
		type("a");
		model.scrollBy(1);
		model.resetSearch();
		assertEquals(0, model.view().getScroll());
	}

	@Test
	public void scrollIsPulledBackWhenTheListShrinks()
	{
		model.scrollBy(4);
		model.setRows(model.view().getRows().subList(0, 4), 4);
		assertEquals(1, model.view().getScroll());
	}

	// Bossing: Vorkath, Zulrah / Slayer: Slayer melee, Vorkath / Unassigned: Barrows
	private void setSectionedRows()
	{
		final SetupEntry vorkath = new SetupEntry("Vorkath", false, null, 1);
		final List<PickerRow> rows = new ArrayList<>();
		rows.add(PickerRow.header(new SetupSection("Bossing", null, new ArrayList<>())));
		rows.add(PickerRow.of(vorkath));
		rows.add(PickerRow.of(new SetupEntry("Zulrah", false, null, 1)));
		rows.add(PickerRow.header(new SetupSection("Slayer", null, new ArrayList<>())));
		rows.add(PickerRow.of(new SetupEntry("Slayer melee", false, null, 1)));
		rows.add(PickerRow.of(vorkath));
		rows.add(PickerRow.UNASSIGNED);
		rows.add(PickerRow.of(new SetupEntry("Barrows", false, null, 1)));
		model.setRows(rows, 4);
	}

	private List<String> rowNames()
	{
		final List<String> names = new ArrayList<>();
		for (PickerRow row : model.view().getRows())
		{
			names.add(row.isBack() ? "<" + row.getSectionName() + ">"
				: row.isHeader() ? "[" + row.getSectionName() + "]" : row.getSetup().getName());
		}
		return names;
	}

	@Test
	public void selectionSkipsSectionHeadings()
	{
		setSectionedRows();
		model.openPalette();
		assertEquals(4, model.view().getTotal());
		assertEquals("Vorkath", model.getSelectedSetup().getName());
		assertEquals(1, model.view().getSelected());

		// nothing above the first heading
		model.moveSelection(-1);
		assertEquals(1, model.view().getSelected());

		model.moveSelection(2);
		assertEquals("Slayer melee", model.getSelectedSetup().getName());
		model.moveSelection(-1);
		assertEquals("Zulrah", model.getSelectedSetup().getName());

		model.pageSelection(5);
		assertEquals("Barrows", model.getSelectedSetup().getName());
		assertEquals(5, model.view().getScroll());

		// going back up to the first setup of a section brings its heading into view too
		model.moveSelection(-3);
		assertEquals("Slayer melee", model.getSelectedSetup().getName());
		assertEquals(3, model.view().getScroll());
	}

	@Test
	public void searchKeepsHeadingsOfSectionsWithMatches()
	{
		setSectionedRows();
		model.openPalette();
		type("vor");
		assertEquals(Arrays.asList("[Bossing]", "Vorkath", "[Slayer]", "Vorkath"), rowNames());
		assertEquals("Vorkath", model.getSelectedSetup().getName());

		model.openPalette();
		type("barr");
		assertEquals(Arrays.asList("[Unassigned]", "Barrows"), rowNames());
	}

	@Test
	public void sectionNameFindsAllOfItsSetups()
	{
		setSectionedRows();
		model.openPalette();
		type("boss");
		assertEquals(Arrays.asList("[Bossing]", "Vorkath", "Zulrah"), rowNames());

		// the section's own setups, plus the setup named after it elsewhere
		model.openPalette();
		type("slayer");
		assertEquals(Arrays.asList("[Slayer]", "Slayer melee", "Vorkath"), rowNames());

		// "Unassigned" isn't a section to search for
		model.openPalette();
		type("unass");
		assertTrue(model.view().getRows().isEmpty());
		assertNull(model.getSelectedSetup());
	}

	@Test
	public void sectionsOpenAsPages()
	{
		setSectionedRows();
		model.setSectionPages(true);
		model.openPalette();
		assertTrue(model.view().isSectionPages());
		assertEquals(Arrays.asList("[Bossing]", "[Slayer]", "[Unassigned]"), rowNames());
		assertEquals(4, model.view().getTotal());

		// headings are what there is to pick
		model.moveSelection(1);
		assertEquals("Slayer", model.getSelectedRow().getSectionName());
		assertNull(model.getSelectedSetup());

		model.openSection(model.getSelectedRow());
		assertEquals(Arrays.asList("<Slayer>", "Slayer melee", "Vorkath"), rowNames());
		assertEquals("Slayer melee", model.getSelectedSetup().getName());
		model.moveSelection(-1);
		assertTrue(model.getSelectedRow().isBack());

		// searching a page stays within it
		type("vor");
		assertEquals(Arrays.asList("<Slayer>", "Vorkath"), rowNames());
		assertEquals("Vorkath", model.getSelectedSetup().getName());
		type("zzz");
		assertEquals(Arrays.asList("<Slayer>"), rowNames());

		// deleting past the start of the search goes back, to the section that was open
		for (int i = 0; i < 6; i++)
		{
			model.backspace();
		}
		assertEquals(Arrays.asList("<Slayer>", "Slayer melee", "Vorkath"), rowNames());
		model.backspace();
		assertEquals(Arrays.asList("[Bossing]", "[Slayer]", "[Unassigned]"), rowNames());
		assertEquals("Slayer", model.getSelectedRow().getSectionName());

		model.openSection(PickerRow.UNASSIGNED);
		assertEquals(Arrays.asList("<Unassigned>", "Barrows"), rowNames());
		model.closeSection();
		assertEquals("Unassigned", model.getSelectedRow().getSectionName());
	}

	@Test
	public void searchingTheListOfSectionsFindsSetupsEverywhere()
	{
		setSectionedRows();
		model.setSectionPages(true);
		model.openPalette();
		type("vor");
		assertEquals(Arrays.asList("[Bossing]", "Vorkath", "[Slayer]", "Vorkath"), rowNames());
		// Enter goes for the setup, though its heading could be picked as well
		assertEquals("Vorkath", model.getSelectedSetup().getName());
		model.moveSelection(-1);
		assertEquals("Bossing", model.getSelectedRow().getSectionName());
		model.moveSelection(2);
		assertEquals("Slayer", model.getSelectedRow().getSectionName());
	}

	@Test
	public void popupAndBankListKeepTheirOwnPage()
	{
		setSectionedRows();
		model.setSectionPages(true);
		model.openSection(model.view().getRows().get(0));
		assertEquals(Arrays.asList("<Bossing>", "Vorkath", "Zulrah"), rowNames());

		// the popup starts from the list of sections
		model.openPalette();
		assertEquals(Arrays.asList("[Bossing]", "[Slayer]", "[Unassigned]"), rowNames());
		model.openSection(model.view().getRows().get(1));
		model.resetSearch();
		assertEquals(Arrays.asList("<Bossing>", "Vorkath", "Zulrah"), rowNames());

		// picking a setup beside the bank leaves its page open, and so does a reload
		model.resetSearch();
		setSectionedRows();
		assertEquals(Arrays.asList("<Bossing>", "Vorkath", "Zulrah"), rowNames());

		// unless the section is gone
		model.setRows(model.view().getRows().subList(1, 3), 2);
		assertFalse(model.view().isSectionPages());
		assertEquals(Arrays.asList("Vorkath", "Zulrah"), rowNames());
	}

	@Test
	public void pagesNeedSections()
	{
		model.setSectionPages(true);
		assertFalse(model.view().isSectionPages());
		assertEquals(7, model.view().getRows().size());

		// and headings can't be opened unless pages are on
		model.setSectionPages(false);
		setSectionedRows();
		model.openSection(model.view().getRows().get(0));
		assertEquals(8, model.view().getRows().size());
	}

	@Test
	public void popupStartsOnTheOpenSetup()
	{
		model.setActiveSetup("Slayer melee");
		model.openPalette();
		assertEquals("Slayer melee", model.getSelectedSetup().getName());
		// and it is scrolled into view once the popup knows how many rows it shows
		model.setVisibleRows(3);
		assertEquals(3, model.view().getScroll());
		assertTrue(model.view().getSelected() < model.view().getScroll() + 3);

		// scrolling away with the wheel isn't fought
		model.scrollBy(-3);
		model.setVisibleRows(3);
		assertEquals(0, model.view().getScroll());

		// searching goes back to the best match as usual
		type("v");
		assertEquals("Vorkath", model.getSelectedSetup().getName());
	}

	@Test
	public void aBankTagIsOpenOnlyWhenTheTagOfItsNameIs()
	{
		final SetupEntry setup = new SetupEntry("Zulrah", false, null, 1);
		final SetupEntry tag = SetupEntry.bankTag("Zulrah", 1);
		// only setups listed: nothing to tell apart
		model.setSetups(Arrays.asList(setup));
		assertFalse(model.view().isMixed());
		model.setSetups(Arrays.asList(setup, tag));
		assertTrue(model.view().isMixed());

		model.setActiveSetup("Zulrah");
		assertTrue(model.view().isActive(setup));
		assertFalse(model.view().isActive(tag));

		model.setActiveSetup("");
		model.setActiveBankTag("Zulrah");
		assertFalse(model.view().isActive(setup));
		assertTrue(model.view().isActive(tag));
		// the popup starts on the tag, not on the setup listed above it
		model.openPalette();
		assertTrue(model.getSelectedSetup().isBankTag());
	}

	@Test
	public void withASetupAndABankTagOpenThePopupStartsOnTheOneOpenedLater()
	{
		final SetupEntry tag = SetupEntry.bankTag("Clues", 1);
		model.setSetups(Arrays.asList(tag, new SetupEntry("Zulrah", false, null, 1)));
		model.setActiveSetup("Zulrah");
		model.setActiveBankTag("Clues");
		model.openPalette();
		assertEquals("Clues", model.getSelectedSetup().getName());

		// the open tag is reported again every tick, which doesn't make it the later one
		model.setActiveSetup("");
		model.setActiveSetup("Zulrah");
		model.setActiveBankTag("Clues");
		model.openPalette();
		assertEquals("Zulrah", model.getSelectedSetup().getName());

		// and when the later one isn't listed, it's the other
		model.setActiveBankTag("A tag that was deleted");
		model.openPalette();
		assertEquals("Zulrah", model.getSelectedSetup().getName());
	}

	@Test
	public void popupStartsAtTheTopWithNothingOpen()
	{
		model.openPalette();
		assertEquals(0, model.view().getSelected());
		model.setActiveSetup("A setup that was deleted");
		model.openPalette();
		assertEquals(0, model.view().getSelected());
	}

	@Test
	public void fuzzySearchOnlyStepsInWhenNothingMatches()
	{
		model.setFuzzySearch(true);
		model.openPalette();
		// an exact match is all that's shown, though "Vardorvis" has v, o, r in order too
		type("vor");
		assertEquals(1, model.view().getRows().size());
		assertEquals("Vorkath", model.getSelectedSetup().getName());
		model.resetSearch();

		// a wrong letter, a missing one, and two swapped
		for (String typo : new String[]{"vorkahh", "zulah", "slyaer"})
		{
			model.openPalette();
			type(typo);
			assertFalse(typo, model.view().getRows().isEmpty());
			model.resetSearch();
		}
		model.openPalette();
		type("zulah");
		assertEquals("Zulrah", model.getSelectedSetup().getName());
		model.resetSearch();

		// letters in order
		model.openPalette();
		type("brws");
		assertEquals("Barrows", model.getSelectedSetup().getName());
		model.resetSearch();

		// nothing like it at all
		model.openPalette();
		type("qqqq");
		assertTrue(model.view().getRows().isEmpty());
	}

	@Test
	public void fuzzySearchCanBeTurnedOff()
	{
		model.setFuzzySearch(false);
		model.openPalette();
		type("zulah");
		assertTrue(model.view().getRows().isEmpty());
	}

	@Test
	public void startingOnTheOpenSetupCanBeTurnedOff()
	{
		model.setStartOnActiveSetup(false);
		model.setActiveSetup("Slayer melee");
		model.openPalette();
		assertEquals(0, model.view().getSelected());
		assertEquals(0, model.view().getScroll());
	}
}

